#!/usr/bin/env python3
"""The check for codegen/t3. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("the generated records match the schema", *ws.run([sys.executable, "tools/gen_records.py", "--check"]))
    ws.check("the schema declares the field", re.search('^\\s+reason:\\s*str\\?', ws.read("schema/records.def"), re.M) is not None)
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom decimal import Decimal\nfrom tally._generated.records import CreditNote\nn = CreditNote("CN-1", "INV-1", Decimal("5.00"), "EUR", d.date(2024, 3, 1), reason="damaged")\nassert CreditNote.from_row(n.to_row()).reason == "damaged"\nassert CreditNote("CN-2", "INV-1", Decimal("1"), "EUR", d.date(2024, 3, 1)).reason is None', env=None))


if __name__ == "__main__":
    main(check)
